import { test, expect } from '@playwright/test';

test.describe('Table Row Hover Highlight', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><head><style>table { border-collapse: collapse; width: 100%; } th, td { border: 1px solid #ddd; padding: 8px; text-align: left; } tbody tr:hover { background-color: #f0f0f0; }</style></head><body><table><thead><tr><th>Name</th><th>Email</th><th>Status</th></tr></thead><tbody><tr><td>John Doe</td><td>john@example.com</td><td>Active</td></tr><tr><td>Jane Smith</td><td>jane@example.com</td><td>Active</td></tr><tr><td>Bob Johnson</td><td>bob@example.com</td><td>Inactive</td></tr></tbody></table></body></html>');
  });

  test('should highlight row on hover', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);

    const initialBgColor = await firstRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    await firstRow.hover();

    const hoverBgColor = await firstRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(hoverBgColor).not.toBe(initialBgColor);
  });

  test('should remove highlight when mouse leaves row', async ({ page }) => {
    const secondRow = page.getByRole('row').nth(2);

    await secondRow.hover();

    const hoverBgColor = await secondRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    await page.mouse.move(0, 0);

    const unhoverBgColor = await secondRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(unhoverBgColor).not.toBe(hoverBgColor);
  });

  test('should highlight different rows independently', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);
    const secondRow = page.getByRole('row').nth(2);

    await firstRow.hover();

    const firstRowHoverColor = await firstRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const secondRowColor = await secondRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(firstRowHoverColor).not.toBe(secondRowColor);

    await secondRow.hover();

    const secondRowHoverColor = await secondRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const firstRowUnhoverColor = await firstRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(secondRowHoverColor).not.toBe(firstRowUnhoverColor);
  });
});
